//! The reference documents in `docs/reference/` are generated by `examples/gen_docs.rs` from the built-in
//! rules. This test regenerates them in memory and fails when a committed file differs, or when a file in the
//! directory is not generated any more. Fix it with `cargo run --release --example gen_docs`.

#[path = "../examples/gen_docs.rs"]
#[allow(dead_code)]
mod gen_docs;

#[test]
fn reference_docs_are_up_to_date() {
    let dir = gen_docs::reference_dir();
    let files = gen_docs::generate();
    let mut problems = Vec::new();
    for (name, text) in &files {
        match std::fs::read_to_string(dir.join(name)) {
            Ok(on_disk) if on_disk == *text => {}
            Ok(_) => problems.push(format!("{name}: differs from the generated text")),
            Err(err) => problems.push(format!("{name}: cannot read ({err})")),
        }
    }
    if let Ok(entries) = std::fs::read_dir(&dir) {
        for entry in entries.flatten() {
            let name = entry.file_name().to_string_lossy().to_string();
            if !files.iter().any(|(n, _)| *n == name) {
                problems.push(format!("{name}: not produced by gen_docs"));
            }
        }
    }
    assert!(
        problems.is_empty(),
        "docs/reference is stale, run `cargo run --release --example gen_docs`:\n{}",
        problems.join("\n")
    );
}

#[test]
fn reference_docs_are_deterministic_and_clean() {
    let a = gen_docs::generate();
    let b = gen_docs::generate();
    assert_eq!(a, b, "generation must not depend on hash order or time");
    for (name, text) in &a {
        assert!(!text.contains('\u{2014}'), "{name} contains an em dash");
        assert!(text.ends_with('\n'), "{name} must end with a newline");
    }
}
